export type InputAction = 'camera-forward'|'camera-backward'|'camera-left'|'camera-right'|'camera-reset'|'confirm-shot'|'pause'|'scoreboard'|'primary';
export interface PointerSnapshot { x:number; y:number; deltaX:number; deltaY:number; wheel:number; primaryDown:boolean }
export interface InputSnapshot { readonly pointer:PointerSnapshot; isDown(action:InputAction):boolean; wasPressed(action:InputAction):boolean; wasReleased(action:InputAction):boolean }
export interface InputManagerOptions { target?:Window; pointerTarget?:HTMLElement|Document; preventContextMenu?:boolean }
const keyActions:Readonly<Record<string,InputAction>>={KeyW:'camera-forward',ArrowUp:'camera-forward',KeyS:'camera-backward',ArrowDown:'camera-backward',KeyA:'camera-left',ArrowLeft:'camera-left',KeyD:'camera-right',ArrowRight:'camera-right',KeyR:'camera-reset',Space:'confirm-shot',Escape:'pause',Tab:'scoreboard'};
export class InputManager implements InputSnapshot {
 readonly pointer:PointerSnapshot={x:0,y:0,deltaX:0,deltaY:0,wheel:0,primaryDown:false};
 private readonly target:Window; private readonly pointerTarget:HTMLElement|Document; private readonly preventContextMenu:boolean;
 private readonly down=new Set<InputAction>(); private readonly pressed=new Set<InputAction>(); private readonly released=new Set<InputAction>(); private disposed=false;
 constructor(options:InputManagerOptions={}){this.target=options.target??window;this.pointerTarget=options.pointerTarget??document;this.preventContextMenu=options.preventContextMenu??true;this.target.addEventListener('keydown',this.onKeyDown);this.target.addEventListener('keyup',this.onKeyUp);this.pointerTarget.addEventListener('pointerdown',this.onPointerDown as EventListener);this.pointerTarget.addEventListener('pointerup',this.onPointerUp as EventListener);this.pointerTarget.addEventListener('pointermove',this.onPointerMove as EventListener);this.pointerTarget.addEventListener('wheel',this.onWheel as EventListener,{passive:false});if(this.preventContextMenu)this.pointerTarget.addEventListener('contextmenu',this.onContextMenu as EventListener);this.target.addEventListener('blur',this.onBlur)}
 isDown(a:InputAction){return this.down.has(a)} wasPressed(a:InputAction){return this.pressed.has(a)} wasReleased(a:InputAction){return this.released.has(a)}
 endFrame(){this.pressed.clear();this.released.clear();this.pointer.deltaX=0;this.pointer.deltaY=0;this.pointer.wheel=0}
 dispose(){if(this.disposed)return;this.disposed=true;this.target.removeEventListener('keydown',this.onKeyDown);this.target.removeEventListener('keyup',this.onKeyUp);this.pointerTarget.removeEventListener('pointerdown',this.onPointerDown as EventListener);this.pointerTarget.removeEventListener('pointerup',this.onPointerUp as EventListener);this.pointerTarget.removeEventListener('pointermove',this.onPointerMove as EventListener);this.pointerTarget.removeEventListener('wheel',this.onWheel as EventListener);this.pointerTarget.removeEventListener('contextmenu',this.onContextMenu as EventListener);this.target.removeEventListener('blur',this.onBlur);this.down.clear();this.pressed.clear();this.released.clear()}
 private setAction(a:InputAction,v:boolean){const had=this.down.has(a);if(v){this.down.add(a);if(!had)this.pressed.add(a)}else{this.down.delete(a);if(had)this.released.add(a)}}
 private readonly onKeyDown=(e:KeyboardEvent)=>{const a=keyActions[e.code];if(!a)return;if(a==='scoreboard'||a==='confirm-shot')e.preventDefault();this.setAction(a,true)};
 private readonly onKeyUp=(e:KeyboardEvent)=>{const a=keyActions[e.code];if(a)this.setAction(a,false)};
 private readonly onPointerDown=(e:PointerEvent)=>{if(e.button!==0)return;this.pointer.primaryDown=true;this.pointer.x=e.clientX;this.pointer.y=e.clientY;this.setAction('primary',true)};
 private readonly onPointerUp=(e:PointerEvent)=>{if(e.button!==0)return;this.pointer.primaryDown=false;this.pointer.x=e.clientX;this.pointer.y=e.clientY;this.setAction('primary',false)};
 private readonly onPointerMove=(e:PointerEvent)=>{this.pointer.x=e.clientX;this.pointer.y=e.clientY;this.pointer.deltaX+=e.movementX;this.pointer.deltaY+=e.movementY};
 private readonly onWheel=(e:WheelEvent)=>{this.pointer.wheel+=e.deltaY;e.preventDefault()};
 private readonly onBlur=()=>{for(const a of this.down)this.released.add(a);this.down.clear();this.pointer.primaryDown=false};
 private readonly onContextMenu=(e:Event)=>e.preventDefault();
}
EOF
